// GENERATED by pxl-tool/bin/spec.rs from host.json — do not edit.
//
// The kernel's own system calls, beside xpute's in the same stream (xpute/spec/ipc/
// sys.json, pxl-kernel io/host.rs, apps/client/src/kernel/host.ts), and the range and the
// files it keeps them in.

// Casing here is the spec's and not Rust's: a name is spelled as the JSON
// spells it, so that one record is indexed by one name on both sides. To
// case them the way Rust would is to rename the protocol.
//
// `dead_code` because a table is generated whole: an entry earns its
// place in the JSON, not by having a caller in this crate.
#![allow(non_upper_case_globals, non_snake_case, dead_code)]

/// The stream's range, laid out by the kernel's map.
pub mod stream {
    /// The range's size. A record names what it moves rather than carrying it, so
    /// a turn's records are words, and a text's bytes the most of them.
    pub const BYTES: u32 = 65536;
    pub const KEYS: &[&str] = &["BYTES"];
}

/// The kernel's calls, each with xpute's PROGRAM bit; a record's call, then its arguments.
pub mod op {
    /// weight, px (f32 bits), max width (f32 bits, 0 for one line), at, lines, then the
    /// text's bytes: the text in the platform's own family at the weight and size, broken
    /// into lines no wider than the width where it can be; at `at`, how many lines, then
    /// a line's end (a byte offset) and its width (f32) apiece, `lines` of them at most
    pub const TEXT_LAYOUT: u32 = 2147483649;
    /// weight, px (f32 bits), color (0xRRGGBBAA), at, width, height, x (f32 bits), then
    /// the text's bytes: one line drawn in the platform's own family, starting at x with
    /// the middle of its em box on the middle row, into `width` by `height` pixels at
    /// `at`, RGBA a byte a channel, top row first, alpha not premultiplied
    pub const TEXT_RASTER: u32 = 2147483650;
    pub const KEYS: &[&str] = &["TEXT_LAYOUT", "TEXT_RASTER"];
}

/// The roots the kernel opens files below (xpute's OPENAT). Below STORAGE a root is a
/// bake, numbered by its kind (pxl-spec bake/published.spec.rs), and a path is an object's
/// name in it.
pub mod root {
    /// The platform's storage; a path is the kernel's name for a file it keeps (`SETTINGS_PATH`, `OBJECTS_PATH`).
    pub const STORAGE: u32 = 256;
    /// The shipped assets; a path is a load's number in decimal (io/load.rs).
    pub const ASSET: u32 = 257;
    pub const KEYS: &[&str] = &["STORAGE", "ASSET"];
}

/// The settings' file below STORAGE.
pub const SETTINGS_PATH: &str = "settings";

/// The placed objects' file below STORAGE. It carries the encoding's version: a blob of
/// an older one is not read, so bump it whenever a change makes an older entry mean
/// something other than it meant when it was written (layer/object/store.rs).
pub const OBJECTS_PATH: &str = "object/v15";
